@import url('https://fonts.googleapis.com/css2?family=Barlow+Condensed:wght@500;600;700;800;900&family=DM+Sans:wght@400;500;600;700;800&display=swap');
:root{--ink:#17263a;--navy:#101b2c;--orange:#ff713d;--yellow:#ffc84a;--mint:#9ae2b6;--white:#fffaf0;--muted:#a9bac6}
*{box-sizing:border-box}html,body{height:100%;margin:0;overflow:hidden;background:var(--navy);font-family:'DM Sans',sans-serif;color:var(--white);touch-action:none;user-select:none;-webkit-user-select:none}.game-shell{position:relative;width:100%;height:100%;min-height:450px;overflow:hidden;background:#b9e8e4}#game{position:absolute;inset:0;width:100%;height:100%;display:block}.topbar{position:absolute;z-index:2;left:0;right:0;top:0;height:80px;padding:20px 4.5%;display:flex;align-items:center;justify-content:space-between;background:linear-gradient(180deg,rgba(17,34,52,.65),transparent)}.brand{display:flex;align-items:center;gap:10px;color:white;text-decoration:none;font-family:'Barlow Condensed',sans-serif;font-weight:800;font-size:16px;letter-spacing:1.6px}.brand b{color:var(--yellow)}.brand-mark{display:grid;place-items:center;width:34px;height:34px;background:var(--orange);border-radius:11px 11px 11px 3px;color:white;font-size:24px;font-weight:900;font-style:italic;box-shadow:0 4px 12px #f86a3c55}.top-stats{display:flex;align-items:center;gap:10px}.coin-pill,.icon-button{height:38px;border:1px solid #ffffff36;background:#18283b9c;backdrop-filter:blur(8px);border-radius:999px;color:white}.coin-pill{min-width:76px;padding:0 13px;display:flex;align-items:center;justify-content:center;gap:8px;font-weight:800}.coin-pill i{font-style:normal;color:var(--yellow);transform:rotate(45deg);font-size:16px}.coin-pill b{font-size:15px}.icon-button{width:38px;font-size:19px;cursor:pointer}.hud{position:absolute;top:98px;left:4.7%;right:4.7%;display:flex;align-items:flex-start;gap:14px;pointer-events:none}.race-card,.fuel-card{background:#12263ccf;border:1px solid #ffffff26;backdrop-filter:blur(10px);box-shadow:0 8px 26px #162c3826;border-radius:13px;padding:12px 16px}.race-card{width:142px}.label,.fuel-title,.best-line,.eyebrow{font-family:'Barlow Condensed',sans-serif;letter-spacing:1.6px;font-weight:700}.label{font-size:10px;color:#b9cbd0}.distance{line-height:1;margin:2px 0 7px}.distance strong{font-family:'Barlow Condensed',sans-serif;font-size:35px;font-weight:800}.distance small{font-size:12px;color:#d4e0df;margin-left:4px}.best-line{font-size:10px;color:#9eb3bd}.best-line span{color:var(--yellow);margin-left:5px}.fuel-card{width:150px;padding:12px 14px}.fuel-title{display:flex;justify-content:space-between;font-size:10px;color:#d6e0d9}.fuel-title span:last-child{color:var(--mint)}.fuel-track{height:6px;border-radius:9px;background:#ffffff28;margin-top:9px;overflow:hidden}.fuel-track i{display:block;width:100%;height:100%;background:linear-gradient(90deg,#7ce8a8,#d6f778);border-radius:9px;transition:width .15s}.air-badge{opacity:0;transform:translateY(7px);transition:.2s;margin:8px auto 0;background:#ffb633;color:#142339;border-radius:9px;padding:7px 12px;display:flex;align-items:center;gap:7px;box-shadow:0 4px 15px #86552335;font-family:'Barlow Condensed',sans-serif;letter-spacing:1px}.air-badge.show{opacity:1;transform:none}.air-badge span{font-size:17px}.air-badge small{font-family:'DM Sans',sans-serif;font-weight:800}.overlay{position:absolute;inset:0;display:grid;place-items:center;z-index:5;background:linear-gradient(90deg,#1023379c 0%,#10233760 42%,#10233720 100%);backdrop-filter:blur(1.5px);transition:opacity .25s}.overlay.hidden{opacity:0;pointer-events:none}.panel{position:relative;background:linear-gradient(145deg,#172b40f2,#102238f2);border:1px solid #ffffff29;box-shadow:0 24px 70px #11213572;border-radius:20px;text-align:center}.start-panel{width:min(510px,90vw);padding:37px 43px 27px;margin-right:28%;}.eyebrow{font-size:11px;color:var(--yellow);letter-spacing:2.4px}.eyebrow span{display:inline-block;width:17px;height:1px;background:var(--yellow);vertical-align:middle;margin:0 7px}.panel h1,.panel h2{font-family:'Barlow Condensed',sans-serif;letter-spacing:1.5px;line-height:.95;margin:14px 0;color:#fff;font-size:66px;font-weight:900}.panel h1 em,.panel h2 em{font-style:normal;color:var(--orange)}.panel p{font-size:13px;line-height:1.65;color:#b4c5cc;margin:12px auto 22px;max-width:330px}.start-meta{display:flex;justify-content:center;gap:15px;color:#e3e9dc;font-size:9px;letter-spacing:.5px;margin:0 0 24px}.start-meta span{white-space:nowrap}.start-meta b{font-weight:700}.primary-btn{border:0;border-radius:9px;background:var(--orange);color:white;height:49px;padding:0 20px;width:100%;font-family:'Barlow Condensed',sans-serif;font-weight:800;font-size:17px;letter-spacing:1.3px;box-shadow:0 5px 0 #c74e29,0 12px 22px #fe673945;cursor:pointer;transition:transform .12s,filter .12s}.primary-btn:hover{filter:brightness(1.08);transform:translateY(-1px)}.primary-btn:active{transform:translateY(3px);box-shadow:0 2px 0 #c74e29}.primary-btn span{font-size:22px;vertical-align:-1px;margin-left:7px}.control-hint{margin-top:20px;font-size:9px;letter-spacing:1px;color:#9bb0ba;white-space:nowrap}.control-hint kbd{font-family:inherit;color:#f9f4e9;border:1px solid #ffffff51;border-radius:3px;padding:2px 5px;font-size:9px;margin:0 3px}.control-hint i{font-style:normal;color:var(--orange);padding:0 4px}.compact-panel{width:min(380px,90vw);padding:36px 38px 28px}.compact-panel h2,.garage-panel h2{font-size:50px}.compact-panel .primary-btn{margin:8px 0}.text-btn{border:0;background:none;color:#b6c8cf;font-family:'Barlow Condensed',sans-serif;font-size:13px;font-weight:700;letter-spacing:1.7px;padding:13px;cursor:pointer}.result-score{display:flex;flex-direction:column;margin:20px 0;color:#fff}.result-score strong{font-family:'Barlow Condensed',sans-serif;font-size:56px;line-height:1}.result-score span{font-size:9px;letter-spacing:2px;color:var(--yellow);font-weight:800}.garage-panel{width:min(455px,92vw);padding:32px 32px 26px;text-align:left}.garage-panel h2{margin:7px 0 4px}.garage-copy{margin:0 0 17px!important}.close-btn{position:absolute;right:20px;top:15px;color:#bccbd0;background:#ffffff12;border:1px solid #ffffff20;border-radius:50%;width:30px;height:30px;font-size:23px;line-height:22px;cursor:pointer}.vehicle-list{display:grid;grid-template-columns:repeat(3,1fr);gap:9px;margin:16px 0}.vehicle-card{border:1px solid #ffffff22;border-radius:11px;background:#ffffff08;padding:10px 6px 9px;text-align:center;cursor:pointer;color:#dce7e1;transition:.15s}.vehicle-card.selected{border-color:var(--yellow);background:#ffd35b17;box-shadow:inset 0 0 0 1px #ffd35b45}.vehicle-card .v-icon{font-size:28px;display:block;margin-bottom:4px}.vehicle-card b{font-family:'Barlow Condensed',sans-serif;display:block;font-size:14px;letter-spacing:.5px}.vehicle-card small{display:block;font-size:8px;color:#a8bac3;margin-top:2px;letter-spacing:.8px}.upgrade-heading{display:flex;justify-content:space-between;color:#9fb3bb;font-family:'Barlow Condensed',sans-serif;font-size:11px;letter-spacing:1.3px;margin:16px 0 8px}.upgrade-heading b{color:var(--yellow)}.upgrade-row{height:29px;display:flex;align-items:center;gap:10px;font-size:10px;color:#d4e0de}.upgrade-row>span{width:91px}.upgrade-row>b{font-family:'Barlow Condensed',sans-serif;color:var(--mint);font-size:10px}.upgrade-bars{display:flex;gap:3px;flex:1}.upgrade-bars i{height:5px;flex:1;border-radius:3px;background:linear-gradient(90deg,#97e2ad,#d1ed77)}.garage-panel>.primary-btn{margin-top:17px}.toast{position:absolute;z-index:4;top:37%;left:50%;transform:translate(-50%,-20px);padding:8px 15px;border-radius:30px;background:#13243bd9;color:#fff;font-family:'Barlow Condensed',sans-serif;font-size:14px;letter-spacing:1.3px;opacity:0;transition:.25s;pointer-events:none}.toast.show{opacity:1;transform:translate(-50%,0)}.bottom-ui{position:absolute;z-index:2;left:0;right:0;bottom:0;height:142px;pointer-events:none;background:linear-gradient(0deg,#11233ac9,transparent)}.speed-wrap{position:absolute;left:5%;bottom:22px}.speedometer{width:86px;height:86px;border:2px solid #ffffff99;border-bottom-color:transparent;border-radius:50%;position:relative;background:#142b3ca6;box-shadow:0 4px 14px #1c364033}.speedometer:before{content:'';position:absolute;inset:6px;border:1px solid #ffffff25;border-radius:50%}.speed-inner{position:absolute;inset:22px 0 auto;text-align:center;display:flex;align-items:center;flex-direction:column}.speed-inner strong{font-family:'Barlow Condensed',sans-serif;font-size:27px;line-height:25px}.speed-inner small{font-size:7px;font-weight:700;letter-spacing:1px;color:#bdd0d3}.speed-needle{position:absolute;width:3px;height:29px;background:var(--yellow);left:40px;top:13px;transform-origin:bottom center;transform:rotate(-48deg);border-radius:3px;transition:transform .15s}.touch-controls{position:absolute;right:5%;bottom:21px;display:flex;gap:12px;pointer-events:auto}.control-btn{height:81px;width:83px;border:1px solid #ffffff63;border-radius:14px;background:#183349bf;backdrop-filter:blur(6px);color:white;display:flex;flex-direction:column;justify-content:center;align-items:center;gap:1px;cursor:pointer;touch-action:none;box-shadow:0 6px 14px #10243b40}.control-btn span{font-size:27px;line-height:30px}.control-btn small{font-family:'Barlow Condensed',sans-serif;letter-spacing:1.4px;font-size:10px;font-weight:700}.control-btn.gas{background:#ff713de3;border-color:#ffc096}.control-btn.gas span{font-size:25px}.control-btn:active,.control-btn.pressed{transform:scale(.94);filter:brightness(1.14)}.bottom-note{position:absolute;bottom:17px;left:50%;transform:translateX(-50%);display:flex;gap:10px;color:#ffffff8c;font-family:'Barlow Condensed',sans-serif;font-size:9px;letter-spacing:2px;white-space:nowrap}.bottom-note span:nth-child(2),.bottom-note span:nth-child(4){color:var(--yellow)}.pause-button{position:absolute;right:4.8%;top:84px;z-index:3;width:34px;height:34px;border:1px solid #ffffff48;border-radius:9px;background:#14283aa8;color:white;font-size:15px;cursor:pointer}
@media(max-width:750px){.topbar{height:65px;padding:14px 5%}.brand{font-size:13px;letter-spacing:1px}.brand-mark{width:30px;height:30px;font-size:21px}.hud{top:77px;left:4%;gap:8px}.race-card{width:115px;padding:10px 12px}.distance strong{font-size:29px}.fuel-card{width:120px;padding:10px 11px}.air-badge{position:absolute;top:97px;left:50%;transform:translate(-50%,7px);margin:0;white-space:nowrap}.air-badge.show{transform:translate(-50%,0)}.pause-button{top:75px;right:4%}.start-panel{margin:0 auto;padding:30px 24px 22px;width:min(450px,91vw)}.panel h1{font-size:58px}.start-panel p{margin-bottom:17px}.start-meta{gap:9px;font-size:8px}.control-hint{font-size:8px;letter-spacing:.4px}.speed-wrap{left:4%;bottom:18px}.speedometer{width:71px;height:71px}.speed-inner{inset:18px 0 auto}.speed-inner strong{font-size:23px}.speed-needle{left:32px;top:10px;height:24px}.touch-controls{right:4%;bottom:16px;gap:8px}.control-btn{width:69px;height:69px;border-radius:12px}.bottom-note{bottom:12px;font-size:7px;gap:6px}.bottom-ui{height:112px}.garage-panel{padding:27px 22px 20px}.vehicle-card .v-icon{font-size:24px}.compact-panel{padding:32px 27px 23px}}
@media(max-width:390px){.brand{font-size:11px}.coin-pill{min-width:59px;height:34px;padding:0 9px}.icon-button{width:34px;height:34px}.top-stats{gap:6px}.start-meta{gap:6px}.control-hint{letter-spacing:0}.control-hint kbd{margin:0 1px;padding:2px 3px}.fuel-card{width:105px}.race-card{width:105px}.fuel-title{font-size:9px}}
@media(max-height:560px){.start-panel{padding-top:20px;padding-bottom:16px}.panel h1{font-size:50px;margin:8px 0}.start-panel p{margin:8px auto 13px}.start-meta{margin-bottom:15px}.control-hint{margin-top:14px}.bottom-ui{height:105px}.garage-panel{padding:19px 25px}.garage-panel h2{font-size:40px}.garage-copy{margin-bottom:8px!important}.vehicle-list{margin:9px 0}.garage-panel>.primary-btn{margin-top:9px}}

(() => {
  const canvas = document.getElementById('game');
  const ctx = canvas.getContext('2d');
  const $ = id => document.getElementById(id);
  const ui = { start: $('startOverlay'), pause: $('pauseOverlay'), crash: $('crashOverlay'), garage: $('garageOverlay'), distance: $('distance'), best: $('best'), fuel: $('fuelBar'), fuelText: $('fuelText'), speed: $('speed'), needle: $('needle'), air: $('airBadge'), airValue: $('airValue'), toast: $('toast') };
  const rides = [
    { name:'TRAIL BLAZER', kind:'jeep', icon:'🚙', color:'#ff7644', accent:'#f7c64a', width:92, power:1 },
    { name:'DIRT ROCKET', kind:'bike', icon:'🏍️', color:'#e95042', accent:'#e9f1dc', width:83, power:1.13 },
    { name:'BIG OX', kind:'truck', icon:'🛻', color:'#7157d7', accent:'#ffca52', width:108, power:.9 }
  ];
  const keys = new Set();
  let W=innerWidth,H=innerHeight,DPR=1, last=0, state='ready', ride=0, best=Number(localStorage.getItem('hill-unlimited-best')||0), sound=true, toastTimer, selectedRide=0;
  let car, camera=0, fuel=100, coins=[], collected=new Set(), lastAir=0, airStart=0, airPoints=0, crashReason='';
  $('best').textContent = `${best} m`;
  function resize(){W=innerWidth;H=innerHeight;DPR=Math.min(devicePixelRatio||1,2);canvas.width=Math.round(W*DPR);canvas.height=Math.round(H*DPR);canvas.style.width=W+'px';canvas.style.height=H+'px';ctx.setTransform(DPR,0,0,DPR,0,0);if(car&&state!=='running')car.y=ground(car.x)-48;}
  addEventListener('resize',resize);resize();
  function ground(x){const h=H*.65;return h+Math.sin(x*.0031)*H*.065+Math.sin(x*.0082+1.4)*H*.026+Math.sin(x*.0014+2.7)*H*.035+Math.sin(x*.015)*H*.008;}
  function slope(x){return (ground(x+2)-ground(x-2))/4;}
  function wrapAngle(a){while(a>Math.PI)a-=Math.PI*2;while(a< -Math.PI)a+=Math.PI*2;return a;}
  function newCar(){return {x:Math.max(145,W*.19),y:ground(Math.max(145,W*.19))-48,vx:0,vy:0,angle:Math.atan(slope(Math.max(145,W*.19))),omega:0,grounded:true,flips:0};}
  car=newCar();
  function toast(text){ui.toast.textContent=text;ui.toast.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>ui.toast.classList.remove('show'),1350);}
  function hideAll(){[ui.start,ui.pause,ui.crash,ui.garage].forEach(el=>el.classList.add('hidden'));}
  function startRun(reset=true){if(reset){car=newCar();fuel=100;collected=new Set();camera=0;airPoints=0;}state='running';hideAll();$('pauseBtn').style.display='block';last=performance.now();}
  function pause(){if(state!=='running')return;state='paused';ui.pause.classList.remove('hidden');keys.clear();}
  function resume(){state='running';ui.pause.classList.add('hidden');last=performance.now();}
  function endRun(reason){if(state!=='running')return;state='ended';crashReason=reason;keys.clear();const d=Math.max(0,Math.floor((car.x-145)/8));$('finalDistance').textContent=d;$('endTitle').textContent=reason==='fuel'?'OUT OF FUEL':'RUN OVER';$('endMessage').textContent=reason==='fuel'?'That was one thirsty ride. Ready for another?':'A spectacular wipeout. The hills are calling you back.';if(d>best){best=d;localStorage.setItem('hill-unlimited-best',best);$('best').textContent=`${best} m`;toast('NEW PERSONAL BEST!');}ui.crash.classList.remove('hidden');$('pauseBtn').style.display='none';}
  function worldPoint(lx,ly){const c=Math.cos(car.angle),s=Math.sin(car.angle);return{x:car.x+lx*c-ly*s,y:car.y+lx*s+ly*c};}
  function seed(n){let x=Math.sin(n*127.1+311.7)*43758.5453;return x-Math.floor(x);}
  function collectables(){const start=Math.floor((camera-100)/310),end=Math.ceil((camera+W+300)/310),items=[];for(let i=start;i<=end;i++){const x=310*i+170+seed(i)*85, gy=ground(x);items.push({type:'coin',x,y:gy-72-seed(i+23)*22,id:`c${i}`});if(i%8===5){const fx=x+120,fy=ground(fx)-73;items.push({type:'fuel',x:fx,y:fy,id:`f${i}`});}}return items;}
  function update(dt){if(state!=='running')return;dt=Math.min(dt,.035);const r=rides[ride], throttle=keys.has('ArrowRight')||keys.has('KeyD')||keys.has('gas'), brake=keys.has('ArrowLeft')||keys.has('KeyA')||keys.has('brake'), leanF=keys.has('ArrowUp')||keys.has('KeyW'),leanB=keys.has('ArrowDown')||keys.has('KeyS');
    const oldGrounded=car.grounded;
    if(throttle){car.vx+=680*r.power*dt;fuel-=.7*dt;}else fuel-=.12*dt;
    if(brake){car.vx-=car.vx>0?940*dt:430*dt;fuel-=.25*dt;}
    car.vx=Math.max(-120,Math.min(650*r.power,car.vx));car.vx*=Math.pow(car.grounded?.994:.999,dt*60);
    car.vy+=1220*dt;
    car.x+=car.vx*dt;car.y+=car.vy*dt;
    car.omega+=((leanB?1:0)-(leanF?1:0))*3.6*dt;
    car.omega*=Math.pow(car.grounded?.79:.985,dt*60);car.angle+=car.omega*dt;
    const axle=r.kind==='truck'?43:37, wheelR=r.kind==='bike'?12:15;let contact=false,maxPen=0,terrainAngle=0;
    for(const side of [-1,1]){const p=worldPoint(side*axle,wheelR*.25),g=ground(p.x),pen=p.y+wheelR-g;if(pen>0){contact=true;maxPen=Math.max(maxPen,pen);terrainAngle+=Math.atan(slope(p.x));}}
    car.grounded=contact;
    if(contact){car.y-=Math.min(maxPen,20);car.vy=Math.min(0,car.vy*.15);const target=terrainAngle/2;car.omega+=(wrapAngle(target-car.angle)*11-car.omega*4.8)*dt;car.angle+=car.omega*dt;}
    if(oldGrounded&&!car.grounded){airStart=car.x;airPoints=0;}
    if(!oldGrounded&&car.grounded){const dist=Math.max(0,car.x-airStart);if(dist>60){const points=Math.floor(dist/12)+Math.max(0,car.flips)*250;airPoints+=points;toast(`BIG AIR!  +${points}`);ui.airValue.textContent=`+${points}`;ui.air.classList.add('show');setTimeout(()=>ui.air.classList.remove('show'),1450);}car.flips=0;}
    if(!car.grounded){if(Math.abs(car.omega)>3.4){car.flips++;car.omega=Math.sign(car.omega)*3.4;}}
    const items=collectables();for(const item of items){if(collected.has(item.id)||Math.abs(item.x-car.x)>42)continue;const dist=Math.hypot(item.x-car.x,item.y-car.y);if(dist<62){collected.add(item.id);if(item.type==='fuel'){fuel=Math.min(100,fuel+37);toast('FUEL UP! +37%');}else toast('COIN COLLECTED · ∞');}}
    fuel=Math.max(0,fuel);if(fuel<=0){endRun('fuel');}
    const nose=worldPoint(0,16);if(car.grounded&&Math.abs(car.angle)>2.38&&nose.y>ground(nose.x)-14){endRun('crash');}
    if(car.y>H+160)endRun('crash');
    camera=Math.max(0,car.x-W*.32);const d=Math.max(0,Math.floor((car.x-145)/8));ui.distance.textContent=d;const kmh=Math.round(Math.abs(car.vx)*.31);ui.speed.textContent=kmh;ui.needle.style.transform=`rotate(${-48+Math.min(130,kmh/2.5)}deg)`;ui.fuel.style.width=fuel+'%';ui.fuelText.textContent=Math.ceil(fuel)+'%';ui.air.classList.toggle('show',!car.grounded&&car.x-airStart>65);
  }
  function roundedRect(x,y,w,h,r){ctx.beginPath();ctx.roundRect(x,y,w,h,r);}
  function drawBackground(){let sky=ctx.createLinearGradient(0,0,0,H);sky.addColorStop(0,'#83cbd0');sky.addColorStop(.58,'#b9e8d2');sky.addColorStop(1,'#e5e9be');ctx.fillStyle=sky;ctx.fillRect(0,0,W,H);
    const sunX=W*.77-camera*.045,sunY=H*.22;ctx.fillStyle='#ffe394';ctx.globalAlpha=.72;ctx.beginPath();ctx.arc(sunX,sunY,48,0,Math.PI*2);ctx.fill();ctx.globalAlpha=1;
    for(let layer=0;layer<3;layer++){const parallax=[.08,.16,.28][layer],base=H*([.58,.63,.69][layer]),amp=H*([.07,.08,.09][layer]);ctx.beginPath();ctx.moveTo(0,H);for(let x=0;x<=W+12;x+=12){const wx=x+camera*parallax;const yy=base+Math.sin(wx*.0021+layer*2)*amp+Math.sin(wx*.005+layer)*amp*.3;ctx.lineTo(x,yy);}ctx.lineTo(W,H);ctx.closePath();ctx.fillStyle=['#7bb9aa','#559d83','#3c785d'][layer];ctx.globalAlpha=[.42,.55,.55][layer];ctx.fill();ctx.globalAlpha=1;}
    // distant floating clouds
    for(let i=0;i<5;i++){const x=((i*270-camera*.12)%(W+360)+(W+360))%(W+360)-100,y=H*(.15+(i%3)*.07);ctx.fillStyle='#ffffff68';ctx.beginPath();ctx.ellipse(x,y,30,9,0,0,Math.PI*2);ctx.ellipse(x+20,y-5,20,12,0,0,Math.PI*2);ctx.ellipse(x+40,y,28,8,0,0,Math.PI*2);ctx.fill();}
  }

function drawTerrain(){ctx.save();ctx.translate(-camera,0);ctx.beginPath();ctx.moveTo(camera-20,H+80);for(let x=camera-20;x<=camera+W+30;x+=8)ctx.lineTo(x,ground(x));ctx.lineTo(camera+W+30,H+100);ctx.closePath();const soil=ctx.createLinearGradient(0,H*.57,0,H);soil.addColorStop(0,'#8bcf82');soil.addColorStop(.045,'#68b771');soil.addColorStop(.055,'#b67a50');soil.addColorStop(1,'#75533e');ctx.fillStyle=soil;ctx.fill();ctx.beginPath();for(let x=camera-20;x<=camera+W+30;x+=8){if(x===camera-20)ctx.moveTo(x,ground(x));else ctx.lineTo(x,ground(x));}ctx.strokeStyle='#d5e587';ctx.lineWidth=5;ctx.lineJoin='round';ctx.stroke();ctx.beginPath();for(let x=camera-20;x<=camera+W+30;x+=8){if(x===camera-20)ctx.moveTo(x,ground(x)+6);else ctx.lineTo(x,ground(x)+6);}ctx.strokeStyle='#4b9b69';ctx.lineWidth=3;ctx.stroke();
