  for(const it of collectables()){if(collected.has(it.id))continue;const x=it.x,y=it.y;if(it.type==='coin'){ctx.save();ctx.translate(x,y);ctx.rotate(Math.sin(performance.now()*.003+x)*.18);ctx.fillStyle='#ffcb48';ctx.strokeStyle='#fff0a1';ctx.lineWidth=3;ctx.beginPath();ctx.arc(0,0,12,0,Math.PI*2);ctx.fill();ctx.stroke();ctx.fillStyle='#d68b2a';ctx.font='bold 14px sans-serif';ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText('∞',0,1);ctx.restore();}else{ctx.save();ctx.translate(x,y);ctx.fillStyle='#ec6542';roundedRect(-11,-15,22,30,5);ctx.fill();ctx.fillStyle='#f8e8bd';roundedRect(-5,-10,10,12,2);ctx.fill();ctx.fillStyle='#fff';ctx.font='bold 9px sans-serif';ctx.textAlign='center';ctx.fillText('F',0,12);ctx.restore();}}
