function wheel(x,y,r){ctx.save();ctx.translate(x,y);ctx.fillStyle='#26313a';ctx.beginPath();ctx.arc(0,0,r,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#0d202d';ctx.lineWidth=3;ctx.stroke();ctx.fillStyle='#a9b5ad';ctx.beginPath();ctx.arc(0,0,r*.47,0,Math.PI*2);ctx.fill();ctx.fillStyle='#677981';ctx.beginPath();ctx.arc(0,0,r*.2,0,Math.PI*2);ctx.fill();for(let i=0;i<6;i++){const a=i*Math.PI/3;ctx.strokeStyle='#71828a';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(Math.cos(a)*r*.23,Math.sin(a)*r*.23);ctx.lineTo(Math.cos(a)*r*.42,Math.sin(a)*r*.42);ctx.stroke();}ctx.restore();}
