  // driver silhouette
  if(r.kind!=='bike'){ctx.fillStyle='#f0bd83';ctx.beginPath();ctx.arc(-2,-bh-8,6,0,Math.PI*2);ctx.fill();ctx.fillStyle='#283b4b';roundedRect(-9,-bh-4,17,12,5);ctx.fill();ctx.fillStyle='#f3cb4d';roundedRect(-8,-bh-16,13,5,3);ctx.fill();}
  ctx.restore();}
function render(){drawBackground();drawTerrain();drawVehicle();if(state==='running'&&car.vx>170){ctx.save();ctx.globalAlpha=Math.min(.24,(car.vx-170)/1600);ctx.strokeStyle='#fff';ctx.lineWidth=2;for(let i=0;i<4;i++){const y=H*.49+i*17;ctx.beginPath();ctx.moveTo(W*.42,y);ctx.lineTo(W*.42+20+(i%2)*30,y);ctx.stroke();}ctx.restore();}}
