(() => {
  const canvas=document.getElementById('game'),ctx=canvas.getContext('2d'),$=id=>document.getElementById(id);
  const ui={start:$('startOverlay'),pause:$('pauseOverlay'),crash:$('crashOverlay'),garage:$('garageOverlay'),distance:$('distance'),best:$('best'),fuel:$('fuelBar'),fuelText:$('fuelText'),speed:$('speed'),needle:$('needle'),air:$('airBadge'),airValue:$('airValue'),toast:$('toast')};
  const rides=[{name:'TRAIL BLAZER',kind:'jeep',icon:'🚙',color:'#ff7644',accent:'#f7c64a',power:1},{name:'DIRT ROCKET',kind:'bike',icon:'🏍️',color:'#e95042',accent:'#e9f1dc',power:1.13},{name:'BIG OX',kind:'truck',icon:'🛻',color:'#7157d7',accent:'#ffca52',power:.9}];
  const keys=new Set();let W=innerWidth,H=innerHeight,DPR=1,last=0,state='ready',ride=0,best=Number(localStorage.getItem('hill-unlimited-best')||0),toastTimer,selectedRide=0,car,camera=0,fuel=100,collected=new Set(),airStart=0,airPoints=0,crashReason='',garageReturn='ready';
  $('best').textContent=`${best} m`;
  function resize(){W=innerWidth;H=innerHeight;DPR=Math.min(devicePixelRatio||1,2);canvas.width=Math.round(W*DPR);canvas.height=Math.round(H*DPR);canvas.style.width=W+'px';canvas.style.height=H+'px';ctx.setTransform(DPR,0,0,DPR,0,0);if(car&&state!=='running')car.y=ground(car.x)-(rides[ride].kind==='bike'?18:22.5);}
  addEventListener('resize',resize);
  function ground(x){return H*.65+Math.sin(x*.0031)*H*.065+Math.sin(x*.0082+1.4)*H*.026+Math.sin(x*.0014+2.7)*H*.035+Math.sin(x*.015)*H*.008;}
  function slope(x){return(ground(x+2)-ground(x-2))/4;}
  function wrapAngle(a){while(a>Math.PI)a-=Math.PI*2;while(a< -Math.PI)a+=Math.PI*2;return a;}
  function newCar(){const x=Math.max(145,W*.19),wr=rides[ride].kind==='bike'?12:15;return{x,y:ground(x)-wr*1.5,vx:0,vy:0,angle:Math.atan(slope(x)),omega:0,grounded:true,flips:0};}
  car=newCar();resize();
  function toast(text){ui.toast.textContent=text;ui.toast.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>ui.toast.classList.remove('show'),1350);}
  function hideAll(){[ui.start,ui.pause,ui.crash,ui.garage].forEach(el=>el.classList.add('hidden'));}
  function startRun(reset=true){if(reset){car=newCar();fuel=100;collected=new Set();camera=0;airPoints=0;}state='running';hideAll();$('pauseBtn').style.display='block';last=performance.now();}
  function pause(){if(state!=='running')return;state='paused';ui.pause.classList.remove('hidden');keys.clear();}
  function resume(){state='running';ui.pause.classList.add('hidden');last=performance.now();}
  function endRun(reason){if(state!=='running')return;state='ended';crashReason=reason;keys.clear();const d=Math.max(0,Math.floor((car.x-145)/8));$('finalDistance').textContent=d;$('endTitle').textContent=reason==='fuel'?'OUT OF FUEL':'RUN OVER';$('endMessage').textContent=reason==='fuel'?'That was one thirsty ride. Ready for another?':'A spectacular wipeout. The hills are calling you back.';if(d>best){best=d;localStorage.setItem('hill-unlimited-best',best);$('best').textContent=`${best} m`;}ui.crash.classList.remove('hidden');$('pauseBtn').style.display='none';}
  function worldPoint(lx,ly){const c=Math.cos(car.angle),s=Math.sin(car.angle);return{x:car.x+lx*c-ly*s,y:car.y+lx*s+ly*c};}
  function seed(n){const x=Math.sin(n*127.1+311.7)*43758.5453;return x-Math.floor(x);}
  function collectables(){const start=Math.floor((camera-100)/310),end=Math.ceil((camera+W+300)/310),items=[];for(let i=start;i<=end;i++){const x=310*i+170+seed(i)*85;items.push({type:'coin',x,y:ground(x)-72-seed(i+23)*22,id:`c${i}`});if(i%8===5){const fx=x+120;items.push({type:'fuel',x:fx,y:ground(fx)-73,id:`f${i}`});}}return items;}
  function update(dt){if(state!=='running')return;dt=Math.min(dt,.035);const r=rides[ride],throttle=keys.has('ArrowRight')||keys.has('KeyD')||keys.has('gas'),brake=keys.has('ArrowLeft')||keys.has('KeyA')||keys.has('brake'),leanF=keys.has('ArrowUp')||keys.has('KeyW'),leanB=keys.has('ArrowDown')||keys.has('KeyS');const oldGrounded=car.grounded;
    if(throttle){car.vx+=680*r.power*dt;fuel-=.7*dt;}else fuel-=.12*dt;if(brake){car.vx-=car.vx>0?940*dt:430*dt;fuel-=.25*dt;}car.vx=Math.max(-120,Math.min(650*r.power,car.vx));car.vx*=Math.pow(car.grounded?0.994:0.999,dt*60);car.vy+=1220*dt;car.x+=car.vx*dt;car.y+=car.vy*dt;car.omega+=((leanB?1:0)-(leanF?1:0))*3.6*dt;car.omega*=Math.pow(car.grounded?0.79:0.985,dt*60);car.angle+=car.omega*dt;
    const axle=r.kind==='truck'?43:37,wr=r.kind==='bike'?12:15;let contact=false,maxPen=0,terrainAngle=0;for(const side of [-1,1]){const p=worldPoint(side*axle,wr*.5),g=ground(p.x),pen=p.y+wr-g;if(pen>0){contact=true;maxPen=Math.max(maxPen,pen);terrainAngle+=Math.atan(slope(p.x));}}car.grounded=contact;
    if(contact){car.y-=Math.min(maxPen,20);car.vy=Math.min(0,car.vy*.15);const target=terrainAngle/2;car.omega+=(wrapAngle(target-car.angle)*11-car.omega*4.8)*dt;car.angle+=car.omega*dt;}
    if(oldGrounded&&!car.grounded){airStart=car.x;airPoints=0;}if(!oldGrounded&&car.grounded){const dist=Math.max(0,car.x-airStart);if(dist>60){const points=Math.floor(dist/12)+Math.max(0,car.flips)*250;airPoints+=points;toast(`BIG AIR!  +${points}`);ui.airValue.textContent=`+${points}`;ui.air.classList.add('show');setTimeout(()=>ui.air.classList.remove('show'),1450);}car.flips=0;}if(!car.grounded&&Math.abs(car.omega)>3.4){car.flips++;car.omega=Math.sign(car.omega)*3.4;}
    for(const item of collectables()){if(collected.has(item.id)||Math.abs(item.x-car.x)>42)continue;if(Math.hypot(item.x-car.x,item.y-car.y)<62){collected.add(item.id);if(item.type==='fuel'){fuel=Math.min(100,fuel+37);toast('FUEL UP! +37%');}else toast('COIN COLLECTED · ∞');}}
    fuel=Math.max(0,fuel);if(fuel<=0)endRun('fuel');const nose=worldPoint(0,16);if(car.grounded&&Math.abs(car.angle)>2.38&&nose.y>ground(nose.x)-14)endRun('crash');if(car.y>H+160)endRun('crash');camera=Math.max(0,car.x-W*.32);const d=Math.max(0,Math.floor((car.x-145)/8));ui.distance.textContent=d;const kmh=Math.round(Math.abs(car.vx)*.31);ui.speed.textContent=kmh;ui.needle.style.transform=`rotate(${-48+Math.min(130,kmh/2.5)}deg)`;ui.fuel.style.width=fuel+'%';ui.fuelText.textContent=Math.ceil(fuel)+'%';ui.air.classList.toggle('show',!car.grounded&&car.x-airStart>65);
  }
  function roundedRect(x,y,w,h,r){ctx.beginPath();ctx.roundRect(x,y,w,h,r);}
  function drawBackground(){let sky=ctx.createLinearGradient(0,0,0,H);sky.addColorStop(0,'#83cbd0');sky.addColorStop(.58,'#b9e8d2');sky.addColorStop(1,'#e5e9be');ctx.fillStyle=sky;ctx.fillRect(0,0,W,H);const sunX=W*.77-camera*.045,sunY=H*.22;ctx.fillStyle='#ffe394';ctx.globalAlpha=.72;ctx.beginPath();ctx.arc(sunX,sunY,48,0,Math.PI*2);ctx.fill();ctx.globalAlpha=1;
    for(let layer=0;layer<3;layer++){const parallax=[.08,.16,.28][layer],base=H*[.58,.63,.69][layer],amp=H*[.07,.08,.09][layer];ctx.beginPath();ctx.moveTo(0,H);for(let x=0;x<=W+12;x+=12){const wx=x+camera*parallax;ctx.lineTo(x,base+Math.sin(wx*.0021+layer*2)*amp+Math.sin(wx*.005+layer)*amp*.3);}ctx.lineTo(W,H);ctx.closePath();ctx.fillStyle=['#7bb9aa','#559d83','#3c785d'][layer];ctx.globalAlpha=[.42,.55,.55][layer];ctx.fill();ctx.globalAlpha=1;}
    for(let i=0;i<5;i++){const x=((i*270-camera*.12)%(W+360)+(W+360))%(W+360)-100,y=H*(.15+(i%3)*.07);ctx.fillStyle='#ffffff68';ctx.beginPath();ctx.ellipse(x,y,30,9,0,0,Math.PI*2);ctx.ellipse(x+20,y-5,20,12,0,0,Math.PI*2);ctx.ellipse(x+40,y,28,8,0,0,Math.PI*2);ctx.fill();}}

